variantConfig.listHandler:
async (config) => {
  const res = await integration.fetch('/v2/profiles')
  const profiles = await res.json()
  if (!Array.isArray(profiles))
    return []

  return profiles
    .map(profile => {
      const id = profile?.id == null ? '' : String(profile.id)
      const type = profile?.type ? String(profile.type) : ''
      const name = profile?.businessName || profile?.fullName || profile?.name || [profile?.firstName, profile?.lastName].filter(Boolean).join(' ') || id
      const label = type ? `${name} (${type})` : name
      return { id, name: label }
    })
    .filter(profile => profile.id && profile.name)
}
